def icon(name, cls=""):
    """Decorative inline icon, always hidden from screen readers: put the meaning in nearby text or an aria-label."""
    classes = "ic " + str(escape(cls)) if cls else "ic"
    return Markup('<svg class="%s" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" focusable="false">%s</svg>' % (classes, _PATHS[name]))
